def merge_all():
    knowledge_path = "datasets/destinations/destinations_rich_knowledge.json"
    existing = []
    if os.path.exists(knowledge_path):
        with open(knowledge_path, "r", encoding="utf-8") as f:
            existing = json.load(f)

    # Filter out replaced cities
    replaced_cities = set(PAN_INDIA_AND_GLOBAL_DATA.keys())
    kept_records = [d for d in existing if d.get("city") not in replaced_cities]

    new_records = []
    for city, pois in PAN_INDIA_AND_GLOBAL_DATA.items():
        for p in pois:
            p["city"] = city
            p["region"] = "India"
            p["country"] = "India"
            new_records.append(p)

    final_knowledge = new_records + kept_records
    with open(knowledge_path, "w", encoding="utf-8") as f:
        json.dump(final_knowledge, f, indent=2)

    print(f"Successfully integrated all Pan-India POIs! Total in knowledge base: {len(final_knowledge)}")

if __name__ == "__main__":
    merge_all()
